from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    def is_expired(key, t):
        if key not in cache:
            return True
        _, wt = cache[key]
        return t >= wt + ttl

    for op in ops:
        kind = op[0]
        t = op[1]
        key = op[2]

        # First, purge this key if expired
        if key in cache and is_expired(key, t):
            del cache[key]

        if kind == 'put':
            value = op[3]
            if key in cache:
                del cache[key]
            elif len(cache) >= capacity:
                cache.popitem(last=False)
            cache[key] = (value, t)
        else:  # get
            if key in cache:
                value, wt = cache[key]
                del cache[key]
                cache[key] = (value, wt)
                results.append(value)
            else:
                results.append(-1)

    return results

